import java.net.http.*;
import java.net.URI;

var client = HttpClient.newHttpClient();
var json = "{
  "eventTypeKey": "EventRegistration",
  "params": {
    "externalCustomerId": "0f8fad5b-d9cb-469f-a165-70867728950e",
    "registrationId": "REG-100045",
    "eventId": "product_launch_kyiv_2025",
