#import <Foundation/Foundation.h>
NSURL *url = [NSURL URLWithString:@"https://api.example.com/v1/event"];
NSMutableURLRequest *req = [NSMutableURLRequest requestWithURL:url];
req.HTTPMethod = @"POST";
[req setValue:@"application/json" forHTTPHeaderField:@"Content-Type"];
[req setValue:@"Bearer YOUR_TOKEN" forHTTPHeaderField:@"Authorization"];
NSString *json = @"{
  \"eventTypeKey\": \"EventRegistration\",
  \"params\": {
    \"externalCustomerId\": \"0f8fad5b-d9cb-469f-a165-70867728950e\",
    \"registrationId\": \"REG-100045\",
    \"eventId\": \"product_launch_kyiv_2025\",
